<?php
require_once 'auth.php';require_role(['super_admin','registrar']);require_once 'db.php';$message='';$type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf()){$message='Invalid request.';$type='error';}else{$action=$_POST['action']??'';
  try {
  if($action==='grade'||$action==='class'){
   update_academic_rule($conn,$action,(int)($_POST['id']??0),$_POST[$action==='grade'?'min_mark':'min_gpa']??'',$_POST['gpa']??null);
   $message='Validated rule saved. Existing result grades are retained.';
  }
  elseif($action==='repeat_policy'){
   $policy=$_POST['repeat_selection_policy']??'';$cap=trim($_POST['repeat_gpa_cap']??'');$pass=$_POST['minimum_pass_gpa']??'';$allow=isset($_POST['allow_repeat_after_pass'])?'1':'0';
   if(!in_array($policy,['latest','highest','first_pass'],true)||!is_numeric($pass)||!is_finite((float)$pass)||(float)$pass<0||(float)$pass>4||($cap!==''&&(!is_numeric($cap)||!is_finite((float)$cap)||(float)$cap<0||(float)$cap>4)))throw new DomainException('Enter a valid repeat policy and GPA limits.');
   if((float)$pass!==round((float)$pass,2)||($cap!==''&&(float)$cap!==round((float)$cap,2)))throw new DomainException('Use at most two decimal places.');
   mysqli_begin_transaction($conn);
   mysqli_query($conn,"SELECT setting_value FROM system_settings WHERE setting_key='academic_rules_revision' FOR UPDATE");
   if($cap!==''){
    $capNumber=(float)$cap;$st=mysqli_prepare($conn,'SELECT id FROM grade_scales WHERE is_active=1 AND gpa=? LIMIT 1');mysqli_stmt_bind_param($st,'d',$capNumber);mysqli_stmt_execute($st);
    if(!mysqli_fetch_assoc(mysqli_stmt_get_result($st)))throw new DomainException('Repeat GPA cap must match an active grade GPA.');
   }
   foreach(['repeat_selection_policy'=>$policy,'repeat_gpa_cap'=>$cap,'minimum_pass_gpa'=>(string)(float)$pass,'allow_repeat_after_pass'=>$allow] as $key=>$value)academic_setting($conn,$key,$value);
   mysqli_query($conn,'UPDATE document_verifications SET revoked_at=NOW() WHERE revoked_at IS NULL');
   audit_log($conn,'ACADEMIC_POLICY','repeat','',"Selection=$policy; cap=".($cap===''?'none':$cap)."; minimum pass=$pass; allow passed=$allow");
   mysqli_commit($conn);$message='Repeat policy saved. Stored attempt grades stay unchanged; GPA selection uses the saved policy.';
  }
  elseif($action==='lock'){$year=(string)($_POST['year']??'');$sem=(string)($_POST['semester']??'');$batch=trim($_POST['batch']??'');$section=$_POST['section']??'ALL';$locked=isset($_POST['is_locked'])?1:0;$note=trim($_POST['note']??'');if(!valid_year_semester($year,$sem)||($batch!==''&&!preg_match('/^\d{2}$/',$batch))||!in_array($section,['ALL','PS','BS'],true)){$message='Invalid semester lock values.';$type='error';}else{$batchDb=$batch;$by=$_SESSION['admin_username'];$st=mysqli_prepare($conn,"INSERT INTO semester_locks(year,semester,batch,section,is_locked,note,locked_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE is_locked=VALUES(is_locked),note=VALUES(note),locked_by=VALUES(locked_by)");mysqli_stmt_bind_param($st,'ssssiss',$year,$sem,$batchDb,$section,$locked,$note,$by);mysqli_stmt_execute($st);audit_log($conn,$locked?'LOCK':'UNLOCK','semester',$year.'-'.$sem,$batch.' '.$section.' '.$note);$message='Semester lock saved.';}}
  } catch(DomainException $ex){mysqli_rollback($conn);$message=$ex->getMessage();$type='error';} catch(mysqli_sql_exception $ex){mysqli_rollback($conn);$message='Could not save academic settings. Check the database upgrade and try again.';$type='error';}
 }
}
$grades=mysqli_query($conn,'SELECT * FROM grade_scales ORDER BY min_mark DESC');$classes=mysqli_query($conn,'SELECT * FROM class_rules ORDER BY min_gpa DESC');$locks=mysqli_query($conn,'SELECT * FROM semester_locks ORDER BY year,semester,batch,section');
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Academic Rules</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"><style>.academic-page .feature-card{min-width:0}.academic-page .rule-row strong{overflow-wrap:anywhere}@media(max-width:1000px){.academic-page .feature-grid{grid-template-columns:minmax(0,1fr)}}@media(max-width:420px){.academic-page .rule-row{grid-template-columns:minmax(0,1fr) 70px 55px 50px;gap:6px}.academic-page .rule-row.class-rule{grid-template-columns:minmax(0,1fr) 70px 50px}}</style></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content academic-page"><section class="page-heading"><div><span class="page-kicker">Academic Configuration</span><h1>Academic Rules & Semester Locks</h1><p>Control grade thresholds, class boundaries and closed academic periods.</p></div></section><?php if($message):?><div class="message <?=$type?>"><?=e($message)?></div><?php endif;?><div class="feature-grid"><section class="feature-card"><h2>Grade Scale</h2><?php while($g=mysqli_fetch_assoc($grades)):?><form method="post" class="rule-row"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="grade"><input type="hidden" name="id" value="<?=(int)$g['id']?>"><strong><?=e($g['grade'])?></strong><input type="number" name="min_mark" step="0.01" min="0" max="100" value="<?=e($g['min_mark'])?>"><input type="number" name="gpa" step="0.01" min="0" max="4" value="<?=e($g['gpa'])?>"><button>Save</button></form><?php endwhile;?></section><section class="feature-card"><h2>Class Boundaries</h2><?php while($c=mysqli_fetch_assoc($classes)):?><form method="post" class="rule-row class-rule"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="class"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><strong><?=e($c['class_name'])?></strong><input type="number" name="min_gpa" step="0.01" min="0" max="4" value="<?=e($c['min_gpa'])?>"><button>Save</button></form><?php endwhile;?></section></div><section class="feature-card" style="margin-top:20px"><h2>Semester Lock</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="lock"><div class="form-grid-3"><div><label>Year</label><select name="year" required><?php for($i=1;$i<=4;$i++):?><option value="<?=$i?>">Year <?=$i?></option><?php endfor;?></select></div><div><label>Semester</label><select name="semester"><option value="1">Semester 1</option><option value="2">Semester 2</option></select></div><div><label>Batch (optional)</label><input name="batch" pattern="\d{2}" placeholder="e.g. 25"></div></div><div class="form-grid-2"><div><label>Section</label><select name="section"><option>ALL</option><option>PS</option><option>BS</option></select></div><div><label>Note</label><input name="note" placeholder="e.g. Results finalized"></div></div><label class="checkbox-row"><input type="checkbox" name="is_locked" checked> Lock this semester</label><div class="button-row"><input type="submit" value="Save Lock"></div></form><div class="table-wrapper"><table><thead><tr><th>Year</th><th>Semester</th><th>Batch</th><th>Section</th><th>Status</th><th>Note</th></tr></thead><tbody><?php while($l=mysqli_fetch_assoc($locks)):?><tr><td><?=e($l['year'])?></td><td><?=e($l['semester'])?></td><td><?=e($l['batch']?:'All')?></td><td><?=e($l['section'])?></td><td><?=((int)$l['is_locked']===1?'Locked':'Open')?></td><td><?=e($l['note']?:'—')?></td></tr><?php endwhile;?></tbody></table></div></section><section class="feature-card" style="margin-top:20px"><h2>Repeat Examination Policy</h2><p>Choose the faculty-approved rules. Existing marks and grades are never recalculated by saving these settings.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="repeat_policy"><div class="form-grid-3"><div><label>Attempt used for Semester GPA / CGPA</label><select name="repeat_selection_policy"><?php foreach(['latest'=>'Latest published attempt','highest'=>'Highest GPA (latest on a tie)','first_pass'=>'First passing attempt, otherwise latest'] as $k=>$label):?><option value="<?=$k?>" <?=app_setting($conn,'repeat_selection_policy','latest')===$k?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div><label>Repeat GPA cap</label><input type="number" name="repeat_gpa_cap" min="0" max="4" step="0.01" value="<?=e(app_setting($conn,'repeat_gpa_cap',''))?>" placeholder="Blank = no cap"><div class="field-hint">Applies to new repeat attempts. Existing attempts retain their recorded cap.</div></div><div><label>Minimum passing GPA</label><input type="number" name="minimum_pass_gpa" min="0" max="4" step="0.01" required value="<?=e(app_setting($conn,'minimum_pass_gpa','2.00'))?>"></div></div><label class="checkbox-row"><input type="checkbox" name="allow_repeat_after_pass" <?=app_setting($conn,'allow_repeat_after_pass','0')==='1'?'checked':''?>> Allow repeat examinations after a passing result</label><div class="button-row"><button type="submit">Save Repeat Policy</button></div></form></section></main><?php include 'footer.php';?></div></body></html>